package mz.co.aprendaacodar.blog.entity;
import jakarta.persistence.*;import mz.co.aprendaacodar.common.entity.BaseEntity;import mz.co.aprendaacodar.common.enums.Enums.CommentStatus;import mz.co.aprendaacodar.user.entity.User;import java.time.Instant;
@Entity @Table(name="blog_comments") public class BlogComment extends BaseEntity {@ManyToOne(optional=false,fetch=FetchType.LAZY) private BlogPost post;@ManyToOne(optional=false,fetch=FetchType.LAZY) private User author;@Column(nullable=false,columnDefinition="TEXT") private String content;@Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private CommentStatus status=CommentStatus.VISIBLE;@ManyToOne(fetch=FetchType.LAZY) private User moderatedBy;private Instant moderatedAt;private String moderationReason;protected BlogComment(){}public BlogComment(BlogPost p,User a,String c){post=p;author=a;content=c;}public void hide(User admin){status=CommentStatus.HIDDEN;moderatedBy=admin;moderatedAt=Instant.now();}public BlogPost getPost(){return post;}public User getAuthor(){return author;}public String getContent(){return content;}public CommentStatus getStatus(){return status;}}
